function percentOff(price, pct){ var p=price*(1-pct/100); return {final:p, saved:price-p}; }
function fixedOff(price, amount){ var p=price-amount; return {final:p<0?0:p, saved:amount>p?price:amount}; }
function bundle(price, qty, payQty){ if(payQty<=0) return null; var total=price*payQty; return {total:total, perUnit:total/qty}; }
function tiered(price, threshold, offPct){ if(price>=threshold) return percentOff(price, offPct); return {final:price, saved:0}; }
var EXPORTS={percentOff:percentOff, fixedOff:fixedOff, bundle:bundle, tiered:tiered};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DiscountForgePure = EXPORTS; }
